        raise UsageError("filter: empty column in condition %r" % text)
    return text[:at], op, text[at + len(op):]


def _holds(cell, op, value):
    if op == "~":
        return _icontains(cell, value)
    left, right = to_decimal(cell), to_decimal(value)
