    _need_args(args, 2, "filter FILE CONDITION...", more=True)
    conditions = [_parse_condition(c) for c in args[1:]]
    table = load(args[0])
    checks = [(table.index(column), op, value) for column, op, value in conditions]
    return table.with_rows([row for row in table.rows if all(_holds(row[at], op, value) for at, op, value in checks)])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "rows sorted by KEY (COLUMN[:num][:desc])..."),
    "filter": (cmd_filter, "filter FILE CONDITION...", "rows where every CONDITION (COLUMN OP VALUE) holds"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] COMMAND ARGS..." % PROG, "", "commands:"]
