class SortOrderTests(unittest.TestCase):
    def test_orders(self):
        for keys, want in [
            (["name"], ["B", "a", "b", "c", "d"]),                      # code point: B before a
            (["name:desc"], ["d", "c", "b", "a", "B"]),
            (["price"], ["c", "b", "d", "a", "B"]),                     # text: '-2' < '10' < '10' < '10.5' < '9'
            (["price:num"], ["c", "B", "b", "d", "a"]),                 # ties b, d keep file order
            (["price:num:desc"], ["a", "b", "d", "B", "c"]),            # stable also with desc
            (["price:desc:num"], ["a", "b", "d", "B", "c"]),
            (["city", "price:num"], ["b", "d", "a", "c", "B"]),
            (["city", "price:num:desc"], ["a", "b", "d", "B", "c"]),
            (["city:desc", "name"], ["B", "c", "a", "b", "d"]),
        ]:
            with self.subTest(keys):
                self.assertEqual(names(*keys), want)
